-- Apply after 20261127000100. This migration preserves existing usage and ledger rows.
-- The new attempt UUID is generated by the Edge Function, never by the browser.
alter table public.search_quota_reservations add column if not exists attempt_id uuid;

-- Keep the UUID assignment if the administrator who created it is removed.
alter table public.search_quota_special_users
  alter column created_by drop not null,
  drop constraint if exists search_quota_special_users_created_by_fkey,
  add constraint search_quota_special_users_created_by_fkey
    foreign key (created_by) references auth.users(id) on delete set null;

-- Resolve roles directly from Auth so a revoked role cannot survive in an old JWT.
create or replace function public.search_quota_is_admin(p_user_id uuid)
returns boolean language sql stable set search_path = '' as $$
  select exists (select 1 from auth.users as users
                 where users.id = p_user_id and users.raw_app_meta_data->>'role' = 'admin');
$$;

create or replace function public.expire_search_quota_reservations(p_month date)
returns integer language plpgsql security definer set search_path = '' as $$
declare
  utc_now timestamptz;
  expired_count integer := 0;
begin
  insert into public.search_monthly_usage(usage_month, request_count)
  values (p_month, 0) on conflict (usage_month) do nothing;
  perform usage.request_count from public.search_monthly_usage as usage
   where usage.usage_month = p_month for update;
  utc_now := pg_catalog.clock_timestamp();
  with expired as (
    update public.search_quota_reservations as reservation
       set status = 'expired', finished_at = utc_now
     where reservation.usage_month = p_month and reservation.status = 'reserved'
       and reservation.expires_at <= utc_now
    returning reservation.owner_id, reservation.usage_date
  ), daily_delta as (
    select expired.owner_id, expired.usage_date, pg_catalog.count(*)::integer as amount
      from expired group by expired.owner_id, expired.usage_date
  ), daily_update as (
    update public.search_daily_usage as usage
       set request_count = greatest(0, usage.request_count - daily_delta.amount)
      from daily_delta
     where usage.owner_id = daily_delta.owner_id and usage.usage_date = daily_delta.usage_date
    returning 1
  )
  update public.search_monthly_usage as usage
     set request_count = greatest(0, usage.request_count -
       (select pg_catalog.count(*)::integer from expired))
   where usage.usage_month = p_month;
  select pg_catalog.count(*)::integer into expired_count
    from public.search_quota_reservations as reservation
   where reservation.usage_month = p_month and reservation.status = 'expired'
     and reservation.finished_at = utc_now;
  return coalesce(expired_count, 0);
end;
$$;

create or replace function public.get_search_quota_status()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  current_user_id uuid := auth.uid();
  is_admin boolean := public.search_quota_is_admin(current_user_id);
  configured_shelly_id uuid;
  is_shelly boolean := false;
  utc_now timestamptz := pg_catalog.transaction_timestamp();
  utc_date date := pg_catalog.timezone('UTC', utc_now)::date;
  utc_month date := pg_catalog.date_trunc('month', pg_catalog.timezone('UTC', utc_now))::date;
  daily_cap integer;
  monthly_cap integer;
  daily_used integer := 0;
  monthly_used integer := 0;
  daily_remaining integer;
  monthly_remaining integer;
  remaining integer;
begin
  if current_user_id is null then raise exception 'authentication_required' using errcode = '28000'; end if;
  select 5, least(settings.monthly_limit, 1000) into daily_cap, monthly_cap
    from public.search_quota_settings as settings where settings.singleton = true;
  if not found then raise exception 'quota_settings_missing' using errcode = '55000'; end if;
  select special.user_id into configured_shelly_id from public.search_quota_special_users as special
   where special.slot = 'shelly';
  is_shelly := configured_shelly_id is not null and configured_shelly_id = current_user_id;
  if is_shelly then daily_cap := null;
  elsif is_admin then daily_cap := 60;
  end if;

  -- Recover orphaned reservations from the previous UTC month at rollover.
  if exists (select 1 from public.search_quota_reservations as reservation
             where reservation.usage_month < utc_month and reservation.status = 'reserved'
               and reservation.expires_at <= utc_now) then
    perform public.expire_search_quota_reservations(pending.usage_month)
      from (select distinct reservation.usage_month
              from public.search_quota_reservations as reservation
             where reservation.usage_month < utc_month and reservation.status = 'reserved'
               and reservation.expires_at <= utc_now
             order by reservation.usage_month) as pending;
  end if;
  perform public.expire_search_quota_reservations(utc_month);
  select usage.request_count into daily_used from public.search_daily_usage as usage
   where usage.owner_id = current_user_id and usage.usage_date = utc_date;
  select usage.request_count into monthly_used from public.search_monthly_usage as usage
   where usage.usage_month = utc_month;
  daily_remaining := case when daily_cap is null then null else greatest(0, daily_cap - coalesce(daily_used, 0)) end;
  monthly_remaining := greatest(0, monthly_cap - coalesce(monthly_used, 0));
  remaining := case when daily_remaining is null then monthly_remaining else least(daily_remaining, monthly_remaining) end;
  return pg_catalog.jsonb_build_object(
    'today_used', coalesce(daily_used, 0), 'daily_limit', daily_cap,
    'today_remaining', daily_remaining, 'daily_unlimited', daily_cap is null,
    'is_admin', is_admin, 'is_shelly_user', is_shelly,
    'shelly_user_configured', configured_shelly_id is not null,
    'shelly_user_id', case when is_admin then configured_shelly_id else null end,
    'month_used', coalesce(monthly_used, 0), 'monthly_limit', monthly_cap,
    'month_remaining', monthly_remaining, 'remaining', remaining,
    'daily_resets_at', ((utc_date + 1)::timestamp) at time zone 'UTC',
    'monthly_resets_at', ((utc_month + interval '1 month')::timestamp) at time zone 'UTC');
end;
$$;

create or replace function public.admin_set_search_quota_limits(p_monthly_limit integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'authentication_required' using errcode = '28000'; end if;
  if public.search_quota_is_admin(auth.uid()) is not true then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_monthly_limit is null or p_monthly_limit not between 1 and 1000 then
    raise exception 'monthly_quota_out_of_range' using errcode = '22023';
  end if;
  update public.search_quota_settings as settings set monthly_limit = p_monthly_limit,
    updated_at = pg_catalog.clock_timestamp() where settings.singleton = true;
  if not found then raise exception 'quota_settings_missing' using errcode = '55000'; end if;
  return public.get_search_quota_status();
end;
$$;

create or replace function public.admin_set_shelly_user(p_user_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  current_user_id uuid := auth.uid();
begin
  if current_user_id is null then raise exception 'authentication_required' using errcode = '28000'; end if;
  if public.search_quota_is_admin(current_user_id) is not true then
    raise exception 'admin_required' using errcode = '42501';
  end if;
  if p_user_id is null then
    delete from public.search_quota_special_users as special where special.slot = 'shelly';
  else
    if not exists (select 1 from auth.users as users where users.id = p_user_id) then
      raise exception 'auth_user_not_found' using errcode = '22023';
    end if;
    insert into public.search_quota_special_users(slot, user_id, created_by, created_at)
    values ('shelly', p_user_id, current_user_id, pg_catalog.clock_timestamp())
    on conflict (slot) do update set user_id = excluded.user_id,
      created_by = excluded.created_by, created_at = excluded.created_at;
  end if;
  return public.get_search_quota_status();
end;
$$;

create or replace function public.reserve_search_quota(p_request_id uuid, p_user_id uuid, p_attempt_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  current_user_id uuid := p_user_id;
  is_admin boolean := public.search_quota_is_admin(current_user_id);
  configured_shelly_id uuid;
  is_shelly boolean := false;
  utc_now timestamptz := pg_catalog.transaction_timestamp();
  utc_date date := pg_catalog.timezone('UTC', utc_now)::date;
  utc_month date := pg_catalog.date_trunc('month', pg_catalog.timezone('UTC', utc_now))::date;
  daily_cap integer;
  monthly_cap integer;
  daily_used integer := 0;
  monthly_used integer := 0;
  daily_remaining integer;
  monthly_remaining integer;
  prior_status text;
  prior_expiry timestamptz;
begin
  if current_user_id is null then raise exception 'authentication_required' using errcode = '28000'; end if;
  if p_request_id is null or p_attempt_id is null then raise exception 'request_id_required' using errcode = '22023'; end if;
  select 5, least(settings.monthly_limit, 1000) into daily_cap, monthly_cap
    from public.search_quota_settings as settings where settings.singleton = true for share;
  if not found then raise exception 'quota_settings_missing' using errcode = '55000'; end if;
  select special.user_id into configured_shelly_id from public.search_quota_special_users as special
   where special.slot = 'shelly' for share;
  is_shelly := configured_shelly_id is not null and configured_shelly_id = current_user_id;
  if is_shelly then daily_cap := null;
  elsif is_admin then daily_cap := 60;
  end if;

  insert into public.search_monthly_usage(usage_month, request_count)
  values (utc_month, 0) on conflict (usage_month) do nothing;
  insert into public.search_daily_usage(owner_id, usage_date, request_count)
  values (current_user_id, utc_date, 0) on conflict (owner_id, usage_date) do nothing;
  -- Serialize on the shared project/month row, then the caller's daily row.
  perform usage.request_count from public.search_monthly_usage as usage
   where usage.usage_month = utc_month for update;
  perform usage.request_count from public.search_daily_usage as usage
   where usage.owner_id = current_user_id and usage.usage_date = utc_date for update;
  perform public.expire_search_quota_reservations(utc_month);
  utc_now := pg_catalog.clock_timestamp();

  select reservation.status, reservation.expires_at into prior_status, prior_expiry
    from public.search_quota_reservations as reservation
   where reservation.owner_id = current_user_id and reservation.request_id = p_request_id for update;
  if found then
    select usage.request_count into daily_used from public.search_daily_usage as usage
     where usage.owner_id = current_user_id and usage.usage_date = utc_date;
    select usage.request_count into monthly_used from public.search_monthly_usage as usage
     where usage.usage_month = utc_month;
    daily_remaining := case when daily_cap is null then null else greatest(0, daily_cap - coalesce(daily_used, 0)) end;
    monthly_remaining := greatest(0, monthly_cap - coalesce(monthly_used, 0));
    return pg_catalog.jsonb_build_object('ok', false,
      'reason', case when prior_status = 'reserved' and prior_expiry > utc_now then 'duplicate_request' else 'request_closed' end,
      'duplicate', true, 'request_id', p_request_id, 'status', prior_status,
      'today_used', coalesce(daily_used, 0), 'daily_limit', daily_cap, 'today_remaining', daily_remaining,
      'daily_unlimited', daily_cap is null, 'is_admin', is_admin, 'is_shelly_user', is_shelly,
      'month_used', coalesce(monthly_used, 0), 'monthly_limit', monthly_cap,
      'month_remaining', monthly_remaining,
      'remaining', case when daily_remaining is null then monthly_remaining else least(daily_remaining, monthly_remaining) end,
      'daily_resets_at', ((utc_date + 1)::timestamp) at time zone 'UTC',
      'monthly_resets_at', ((utc_month + interval '1 month')::timestamp) at time zone 'UTC');
  end if;

  select usage.request_count into daily_used from public.search_daily_usage as usage
   where usage.owner_id = current_user_id and usage.usage_date = utc_date;
  select usage.request_count into monthly_used from public.search_monthly_usage as usage
   where usage.usage_month = utc_month;
  if (daily_cap is not null and daily_used >= daily_cap) or monthly_used >= monthly_cap then
    daily_remaining := case when daily_cap is null then null else greatest(0, daily_cap - daily_used) end;
    monthly_remaining := greatest(0, monthly_cap - monthly_used);
    return pg_catalog.jsonb_build_object('ok', false,
      'reason', case when daily_cap is not null and daily_used >= daily_cap then 'daily' else 'monthly' end,
      'duplicate', false, 'today_used', daily_used, 'daily_limit', daily_cap, 'today_remaining', daily_remaining,
      'daily_unlimited', daily_cap is null, 'is_admin', is_admin, 'is_shelly_user', is_shelly,
      'month_used', monthly_used, 'monthly_limit', monthly_cap, 'month_remaining', monthly_remaining,
      'remaining', case when daily_remaining is null then monthly_remaining else least(daily_remaining, monthly_remaining) end,
      'daily_resets_at', ((utc_date + 1)::timestamp) at time zone 'UTC',
      'monthly_resets_at', ((utc_month + interval '1 month')::timestamp) at time zone 'UTC');
  end if;

  -- Claim the globally unique request before touching either counter.
  insert into public.search_quota_reservations
    (owner_id, request_id, attempt_id, usage_date, usage_month, status, created_at, expires_at)
  values (current_user_id, p_request_id, p_attempt_id, utc_date, utc_month, 'reserved',
          utc_now, utc_now + interval '5 minutes')
  on conflict (request_id) do nothing;
  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'request_closed', 'duplicate', true);
  end if;
  update public.search_daily_usage as usage set request_count = usage.request_count + 1
   where usage.owner_id = current_user_id and usage.usage_date = utc_date;
  update public.search_monthly_usage as usage set request_count = usage.request_count + 1
   where usage.usage_month = utc_month;

  daily_remaining := case when daily_cap is null then null else greatest(0, daily_cap - daily_used - 1) end;
  monthly_remaining := greatest(0, monthly_cap - monthly_used - 1);
  return pg_catalog.jsonb_build_object('ok', true, 'reason', null, 'duplicate', false,
    'request_id', p_request_id, 'status', 'reserved',
    'today_used', daily_used + 1, 'daily_limit', daily_cap, 'today_remaining', daily_remaining,
    'daily_unlimited', daily_cap is null, 'is_admin', is_admin, 'is_shelly_user', is_shelly,
    'month_used', monthly_used + 1, 'monthly_limit', monthly_cap, 'month_remaining', monthly_remaining,
    'remaining', case when daily_remaining is null then monthly_remaining else least(daily_remaining, monthly_remaining) end,
    'daily_resets_at', ((utc_date + 1)::timestamp) at time zone 'UTC',
    'monthly_resets_at', ((utc_month + interval '1 month')::timestamp) at time zone 'UTC');
end;
$$;

create or replace function public.confirm_search_quota(p_request_id uuid, p_user_id uuid, p_attempt_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  current_user_id uuid := p_user_id;
  reservation_date date;
  reservation_month date;
  reservation_status text;
  reservation_expiry timestamptz;
  utc_now timestamptz;
begin
  if current_user_id is null then raise exception 'authentication_required' using errcode = '28000'; end if;
  if p_request_id is null or p_attempt_id is null then raise exception 'request_id_required' using errcode = '22023'; end if;
  select reservation.usage_date, reservation.usage_month into reservation_date, reservation_month
    from public.search_quota_reservations as reservation
   where reservation.owner_id = current_user_id and reservation.request_id = p_request_id
     and reservation.attempt_id = p_attempt_id;
  if not found then return pg_catalog.jsonb_build_object('confirmed', false, 'reason', 'not_found'); end if;
  perform usage.request_count from public.search_monthly_usage as usage where usage.usage_month = reservation_month for update;
  perform usage.request_count from public.search_daily_usage as usage
   where usage.owner_id = current_user_id and usage.usage_date = reservation_date for update;
  select reservation.status, reservation.expires_at into reservation_status, reservation_expiry
    from public.search_quota_reservations as reservation
   where reservation.owner_id = current_user_id and reservation.request_id = p_request_id
     and reservation.attempt_id = p_attempt_id for update;
  if not found then
    return pg_catalog.jsonb_build_object('confirmed', false, 'reason', 'not_found');
  end if;
  utc_now := pg_catalog.clock_timestamp();
  if reservation_status = 'consumed' then
    return pg_catalog.jsonb_build_object('confirmed', true, 'duplicate', true, 'request_id', p_request_id);
  end if;
  if reservation_status <> 'reserved' then
    return pg_catalog.jsonb_build_object('confirmed', false, 'reason', reservation_status, 'request_id', p_request_id);
  end if;
  if reservation_expiry <= utc_now then
    update public.search_quota_reservations as reservation set status = 'expired', finished_at = utc_now
     where reservation.owner_id = current_user_id and reservation.request_id = p_request_id
     and reservation.attempt_id = p_attempt_id;
    update public.search_daily_usage as usage set request_count = greatest(0, usage.request_count - 1)
     where usage.owner_id = current_user_id and usage.usage_date = reservation_date;
    update public.search_monthly_usage as usage set request_count = greatest(0, usage.request_count - 1)
     where usage.usage_month = reservation_month;
    return pg_catalog.jsonb_build_object('confirmed', false, 'reason', 'expired', 'request_id', p_request_id);
  end if;
  update public.search_quota_reservations as reservation set status = 'consumed', finished_at = utc_now
   where reservation.owner_id = current_user_id and reservation.request_id = p_request_id
     and reservation.attempt_id = p_attempt_id;
  return pg_catalog.jsonb_build_object('confirmed', true, 'duplicate', false, 'request_id', p_request_id);
end;
$$;

create or replace function public.refund_search_quota(p_request_id uuid, p_user_id uuid, p_attempt_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  current_user_id uuid := p_user_id;
  reservation_date date;
  reservation_month date;
  reservation_status text;
  utc_now timestamptz;
begin
  if current_user_id is null then raise exception 'authentication_required' using errcode = '28000'; end if;
  if p_request_id is null or p_attempt_id is null then raise exception 'request_id_required' using errcode = '22023'; end if;
  select reservation.usage_date, reservation.usage_month into reservation_date, reservation_month
    from public.search_quota_reservations as reservation
   where reservation.owner_id = current_user_id and reservation.request_id = p_request_id
     and reservation.attempt_id = p_attempt_id;
  if not found then return pg_catalog.jsonb_build_object('refunded', false, 'duplicate', false, 'reason', 'not_found'); end if;
  -- Keep the same lock order as reserve/confirm for concurrent settlement.
  perform usage.request_count from public.search_monthly_usage as usage where usage.usage_month = reservation_month for update;
  perform usage.request_count from public.search_daily_usage as usage
   where usage.owner_id = current_user_id and usage.usage_date = reservation_date for update;
  select reservation.status into reservation_status
    from public.search_quota_reservations as reservation
   where reservation.owner_id = current_user_id and reservation.request_id = p_request_id
     and reservation.attempt_id = p_attempt_id for update;
  if not found then
    return pg_catalog.jsonb_build_object('refunded', false, 'reason', 'not_found');
  end if;
  utc_now := pg_catalog.clock_timestamp();
  if reservation_status = 'reserved' then
    update public.search_quota_reservations as reservation set status = 'refunded', finished_at = utc_now
     where reservation.owner_id = current_user_id and reservation.request_id = p_request_id
     and reservation.attempt_id = p_attempt_id;
    update public.search_daily_usage as usage set request_count = greatest(0, usage.request_count - 1)
     where usage.owner_id = current_user_id and usage.usage_date = reservation_date;
    update public.search_monthly_usage as usage set request_count = greatest(0, usage.request_count - 1)
     where usage.usage_month = reservation_month;
    return pg_catalog.jsonb_build_object('refunded', true, 'duplicate', false, 'request_id', p_request_id);
  end if;
  return pg_catalog.jsonb_build_object('refunded', false,
    'duplicate', reservation_status in ('refunded', 'expired'),
    'reason', case when reservation_status in ('refunded', 'expired') then 'already_refunded' else 'already_confirmed' end,
    'request_id', p_request_id);
end;
$$;

-- Legacy signatures and helpers are private. Browser RPCs never receive settlement privileges.
revoke all on function public.reserve_search_quota(uuid) from public, anon, authenticated, service_role;
revoke all on function public.confirm_search_quota(uuid) from public, anon, authenticated, service_role;
revoke all on function public.refund_search_quota(uuid) from public, anon, authenticated, service_role;
revoke all on function public.expire_search_quota_reservations() from public, anon, authenticated, service_role;
revoke all on function public.expire_search_quota_reservations(date) from public, anon, authenticated, service_role;
revoke all on function public.search_quota_is_admin(uuid) from public, anon, authenticated, service_role;
revoke all on function public.reserve_search_quota(uuid, uuid, uuid) from public, anon, authenticated, service_role;
revoke all on function public.confirm_search_quota(uuid, uuid, uuid) from public, anon, authenticated, service_role;
revoke all on function public.refund_search_quota(uuid, uuid, uuid) from public, anon, authenticated, service_role;
revoke all on function public.get_search_quota_status() from public, anon, authenticated, service_role;
revoke all on function public.admin_set_search_quota_limits(integer) from public, anon, authenticated, service_role;
revoke all on function public.admin_set_search_quota_limits(integer, integer) from public, anon, authenticated, service_role;
revoke all on function public.admin_set_shelly_user(uuid) from public, anon, authenticated, service_role;
grant execute on function public.reserve_search_quota(uuid, uuid, uuid) to service_role;
grant execute on function public.confirm_search_quota(uuid, uuid, uuid) to service_role;
grant execute on function public.refund_search_quota(uuid, uuid, uuid) to service_role;
grant execute on function public.get_search_quota_status() to authenticated;
grant execute on function public.admin_set_search_quota_limits(integer) to authenticated;
grant execute on function public.admin_set_search_quota_limits(integer, integer) to authenticated;
grant execute on function public.admin_set_shelly_user(uuid) to authenticated;
